{
  "query": "query($zencargoReferences: [String!]) { bookings(zencargoReferences: $zencargoReferences) { nodes { zencargoReference bookingStage { value } bookingDocuments { documentType description assetUrl } } } }",
  "variables": { "zencargoReferences": ["ZTEST-1"] }
}

{
  "query": "query($zencargoReferences: [String!]) { bookings(zencargoReferences: $zencargoReferences) { nodes { zencargoReference modeOfTransport loadType incoterms { value } consignor { label { long } } consignee { label { long } } forwarder { label { long } } } } }",
  "variables": { "zencargoReferences": ["ZTEST-1"] }
}

{
  "query": "query($zencargoReferences: [String!]) { bookings(zencargoReferences: $zencargoReferences) { nodes { zencargoReference scheduledLegs { modeOfTransport fromTerminal { name unlocode } toTerminal { name unlocode } estimatedDepartureDate estimatedArrivalDate actualDepartureLocalDateTime actualArrivalLocalDateTime } voyageMilestone { name occurred latestEstimate actual vesselName portName } } } }",
  "variables": { "zencargoReferences": ["ZTEST-1"] }
}

{
  "query": "query($zencargoReferences: [String!]) { bookings(zencargoReferences: $zencargoReferences) { nodes { cargoJourneyDetails { cargoId estimatedCollectionDateTime actualCollectionDateTime estimatedDeliveryDateTime actualDeliveryDateTime } } } }",
  "variables": { "zencargoReferences": ["ZTEST-1"] }
}

{
  "query": "mutation($input: CreateOrderInput!) { purchaseOrdersCreateOrder(input: $input) { purchaseOrder { orderReferenceNumber } errors { path message } } }",
  "variables": {
    "input": {
      "orderReferenceNumber": "PO-SEAWARD-2",
      "orderDate": "2021-01-01",
      "manufacturerID": "uuid12345",
      "originID": "uuid12345",
      "destinationID": "uuid98765",
      "orderedLineItems": [ { "productSku": "10000", "quantityOrdered": 10000, "cbm": 32.0, "initialCargoReadyDate": "2020-03-16", "requiredDeliveryDate": "2020-05-04", "erpLineId": "YOUR_ERP_LINE_ID" } ]
    }
  }
}

{
  "query": "query($ref: String!) { purchaseOrder(orderReferenceNumber: $ref) { orderReferenceNumber orderDate orderedLineItems { product { skuCode } quantityOrdered lots { quantityFulfilled cargoReadyDate { date } } } } }",
  "variables": { "ref": "PO-SEAWARD-2" }
}

{
  "query": "mutation($input: ClosePurchaseOrderInput!) { purchaseOrdersCloseOrder(input: $input) { purchaseOrder { orderReferenceNumber } errors { path message } } }",
  "variables": { "input": { "orderReferenceNumber": "PO-SEAWARD-2" } }
}

{
  "query": "mutation($input: CreateCoreProductInput!) { createCoreProduct(input: $input) { coreProduct { id skuCode name } errors { path message } } }",
  "variables": { "input": { "name": "Frozen Banana", "skuCode": "10000" } }
}

{
  "query": "query($findBy: PackingListFindBy!) { packingLists(findBy: $findBy) { nodes { cargo { grossWeight { value unit } } lines { quantity lot { product { skuCode } } } } } }",
  "variables": { "findBy": { "key": "BOOKING_REFERENCE", "value": "ZTEST-1" } }
}

{
  "query": "query { account(uuid: \"a7353774-9795-434b-a1f8-7582b6afd345\") { label { long } products(first: 5) { nodes { name skuCode } } } }"
}

{
  "query": "query($accountId: String!, $filters: SearchAssignableAccountsFiltersInput!) { searchAssignableAccounts(accountId: $accountId, searchAssignableAccountsFiltersInput: $filters) { nodes { account { label { long } } connectionType } } }",
  "variables": { "accountId": "a7353774-9795-434b-a1f8-7582b6afd345", "filters": { "accountTypes": ["SUPPLIER"], "searchQuery": "" } }
}
